import { Field, Int, ObjectType } from '@nestjs/graphql';
import {
  IsBoolean,
  IsDate,
  IsInt,
  IsOptional,
  IsString,
} from 'class-validator';

@ObjectType()
export class Book {
  @Field(() => String)
  @IsString()
  isbn: string;

  @Field(() => String)
  @IsString()
  title: string;

  @Field(() => Int)
  @IsInt()
  pages: number;

  @Field(() => Date, { nullable: true })
  @IsOptional()
  @IsDate()
  publishedAt?: Date;

  @Field(() => Boolean)
  @IsBoolean()
  inPrint: boolean;
}

