1	import type { ParsedField } from './parser.ts';
2	import type { ResourceNames } from '../shared/names.ts';
3	import { dasherize } from '../shared/names.ts';
4	
5	/** Embedded sub-schemas: class name ('Calibrated') → its parsed fields. */
6	export type SubSchemas = Map<string, ParsedField[]>;
7	
8	type Mode = 'entity' | 'input';
9	
10	const isSub = (f: ParsedField): boolean => f.type === 'SubSchema';
11	
12	const gqlTypeName = (f: ParsedField, mode: Mode): string => {
13	  if (isSub(f)) {
14	    return mode === 'entity' ? f.subSchemaClass! : `${f.subSchemaClass!}Input`;
15	  }
16	  return { String: 'String', Number: 'Int', Boolean: 'Boolean', Date: 'Date' }[
17	    f.type as Exclude<ParsedField['type'], 'SubSchema'>
18	  ];
19	};
20	
21	const tsTypeName = (f: ParsedField, mode: Mode): string => {
22	  if (isSub(f)) return gqlTypeName(f, mode);
23	  return { String: 'string', Number: 'number', Boolean: 'boolean', Date: 'Date' }[
24	    f.type as Exclude<ParsedField['type'], 'SubSchema'>
25	  ];
26	};
27	
28	const validator = (f: ParsedField): string => {
29	  if (f.type === 'String' && /email/i.test(f.name)) return 'IsEmail';
30	  return { String: 'IsString', Number: 'IsInt', Boolean: 'IsBoolean', Date: 'IsDate' }[
31	    f.type as Exclude<ParsedField['type'], 'SubSchema'>
32	  ];
33	};
34	
35	// A field is exposed as optional when creating: not required, or filled by a default.
36	export const optionalOnCreate = (f: ParsedField): boolean =>
37	  !f.required || f.hasDefault;
38	// A field is nullable on the entity when nothing guarantees a value.
39	export const nullableOnEntity = (f: ParsedField): boolean =>
40	  !f.required && !f.hasDefault;
41	
42	export const keyFields = (fields: ParsedField[]): ParsedField[] => {
43	  const primitives = fields.filter((f) => !isSub(f));
44	  if (primitives.length === 0) {
45	    throw new Error(
46	      'The schema needs at least one primitive field to serve as a lookup key.',
47	    );
48	  }
49	  const uniques = primitives.filter((f) => f.unique);
50	  return uniques.length > 0 ? uniques : primitives;
51	};
52	
53	const fieldBlock = (
54	  f: ParsedField,
55	  optional: boolean,
56	  mode: Mode,
57	): string => {
58	  const typeName = gqlTypeName(f, mode);
59	  const lines = [
60	    `  @Field(() => ${typeName}${optional ? ', { nullable: true }' : ''})`,
61	  ];
62	  if (optional) lines.push('  @IsOptional()');
63	  if (isSub(f)) {
64	    lines.push('  @ValidateNested()');
65	    lines.push(`  @Type(() => ${typeName})`);
66	  } else {
67	    lines.push(`  @${validator(f)}()`);
68	  }
69	  lines.push(`  ${f.name}${optional ? '?' : ''}: ${tsTypeName(f, mode)};`);
70	  return lines.join('\n');
71	};
72	
73	interface ClassSpec {
74	  className: string;
75	  kind: 'ObjectType' | 'InputType';
76	  mode: Mode;
77	  fields: ParsedField[];
78	  optionalOf: (f: ParsedField) => boolean;
79	  extraValidators?: string[];
80	  extraImports?: string[];
81	}
82	
83	const classImports = ({
84	  kind,
85	  mode,
86	  fields,
87	  optionalOf,
88	  extraValidators = [],
89	  extraImports = [],
90	}: Omit<ClassSpec, 'className'>): string => {
91	  const gqlNames = ['Field', kind];
92	  if (fields.some((f) => f.type === 'Number')) gqlNames.push('Int');
93	
94	  const validatorNames = new Set<string>(
95	    fields.filter((f) => !isSub(f)).map(validator),
96	  );
97	  if (fields.some(optionalOf)) validatorNames.add('IsOptional');
98	  if (fields.some(isSub)) validatorNames.add('ValidateNested');
99	  extraValidators.forEach((name) => validatorNames.add(name));
100	
101	  const lines = [
102	    `import { ${gqlNames.sort().join(', ')} } from '@nestjs/graphql';`,
103	    `import {\n${[...validatorNames]
104	      .sort()
105	      .map((name) => `  ${name},`)
106	      .join('\n')}\n} from 'class-validator';`,
107	  ];
108	
109	  if (fields.some(isSub) || extraValidators.includes('ValidateNested')) {
110	    lines.push(`import { Type } from 'class-transformer';`);
111	  }
112	
113	  fields.filter(isSub).forEach((f) => {
114	    const dashed = dasherize(f.subSchemaClass!);
115	    lines.push(
116	      mode === 'entity'
117	        ? `import { ${f.subSchemaClass!} } from './${dashed}.entity';`
118	        : `import { ${f.subSchemaClass!}Input } from './${dashed}.input.dto';`,
119	    );
120	  });
121	
122	  return [...lines, ...extraImports].join('\n');
123	};
124	
125	const classTemplate = (spec: ClassSpec): string => `${classImports(spec)}
126	
127	@${spec.kind}()
128	export class ${spec.className} {
129	${spec.fields.map((f) => fieldBlock(f, spec.optionalOf(f), spec.mode)).join('\n\n')}
130	}
131	`;
132	
133	export const entityTemplate = (n: ResourceNames, fields: ParsedField[]): string =>
134	  classTemplate({
135	    className: n.singularClass,
136	    kind: 'ObjectType',
137	    mode: 'entity',
138	    fields,
139	    optionalOf: nullableOnEntity,
140	  });
141	
142	export const subEntityTemplate = (className: string, fields: ParsedField[]): string =>
143	  classTemplate({
144	    className,
145	    kind: 'ObjectType',
146	    mode: 'entity',
147	    fields,
148	    optionalOf: nullableOnEntity,
149	  });
150	
151	export const createDtoTemplate = (n: ResourceNames, fields: ParsedField[]): string =>
152	  classTemplate({
153	    className: `Create${n.singularClass}Input`,
154	    kind: 'InputType',
155	    mode: 'input',
156	    fields,
157	    optionalOf: optionalOnCreate,
158	  });
159	
160	export const subInputTemplate = (className: string, fields: ParsedField[]): string =>
161	  classTemplate({
162	    className: `${className}Input`,
163	    kind: 'InputType',
164	    mode: 'input',
165	    fields,
166	    optionalOf: optionalOnCreate,
167	  });
168	
169	export const getDtoTemplate = (n: ResourceNames, fields: ParsedField[]): string =>
170	  classTemplate({
171	    className: `Get${n.singularClass}Input`,
172	    kind: 'InputType',
173	    mode: 'input',
174	    fields: keyFields(fields),
175	    optionalOf: () => true,
176	  });
177	
178	export const updateDtoTemplate = (n: ResourceNames, fields: ParsedField[]): string => `${classTemplate(
179	  {
180	    className: `Update${n.singularClass}Payload`,
181	    kind: 'InputType',
182	    mode: 'input',
183	    fields,
184	    optionalOf: () => true,
